-- Passage-structure links, their notes in plain English (owner rule): no working notes or table names ("verified in
-- qr_word_occurrence at 3, 5 …"), no ASCII transliteration (al-AZIZ, iqab, istinaf bayani) — Arabic in Arabic script.
UPDATE qr_passage_section SET data_json = json_set(data_json, '$.relation.note', 'This passage sets up the next one. Ibn ʿĀshūr (34:3): naming what goes into the earth and comes out of it already points to the dead rising, so when the next passage denies the Hour, it walks into an answer already given.') WHERE id = 'QR:PSEC:34:1-2:premise';
UPDATE qr_passage_section SET data_json = json_set(data_json, '$.relation.note', 'This passage grounds the next one, not the other way round. In 40:4 the Prophet is told not to be impressed by the disbelievers’ power; the reason is الْعَزِيز in 40:2: their might against His. Ibn ʿĀshūr says 40:4 grows out of تَنْزِيلُ الْكِتَابِ. Al-Rāzī reads الْعَزِيز as “the One without equal” — and the One without equal needs nothing, so His acts are wise, which is exactly what the disputers deny. That is why Abū Ḥayyān and al-Rāzī read 40:1–6 as one block.') WHERE id = 'QR:PS:40:1-3:rel15a';
UPDATE qr_passage_section SET data_json = json_set(data_json, '$.relation.note', 'عِقَاب and عَاقِبَة are one root (ع ق ب), at 40:3, 5, 21, 22 and 82. “Severe in penalty” in 40:3 and “see how it ended” in the two travel verses are the same word: what the sūra tells you to go and look at is the attribute it opened with.') WHERE id = 'QR:PS:40:1-3:rel16a';
UPDATE qr_passage_section SET data_json = json_set(data_json, '$.relation.note', 'The complaint and the standing offer: the offer comes after the complaint.') WHERE id = 'QR:PS:40:10-12:rel2a';
UPDATE qr_passage_section SET data_json = json_set(data_json, '$.relation.note', 'Word for word, but for one pronoun: both passages give signs, then the command to call on Him.') WHERE id = 'QR:PS:40:13-17:rel3a';
UPDATE qr_passage_section SET data_json = json_set(data_json, '$.relation.note', 'The question of the Last Day is quoted back inside Pharaoh’s court, with the answer changed.') WHERE id = 'QR:PS:40:13-17:rel9a';
UPDATE qr_passage_section SET data_json = json_set(data_json, '$.relation.note', 'Both open with a travel verse, then the proof formula; two arcs of the sūra cross here.') WHERE id = 'QR:PS:40:21-22:rel4a';
UPDATE qr_passage_section SET data_json = json_set(data_json, '$.relation.note', '40:22 also carries شَدِيدُ الْعِقَابِ word for word from 40:3, so this passage holds both forms of the root.') WHERE id = 'QR:PS:40:21-22:rel16b';
UPDATE qr_passage_section SET data_json = json_set(data_json, '$.relation.note', 'The same root and the same instruction: Mūsā seeks refuge, the Prophet is told to; against the arrogant (مُتَكَبِّر) in both.') WHERE id = 'QR:PS:40:23-27:rel7a';
UPDATE qr_passage_section SET data_json = json_set(data_json, '$.relation.note', 'The same clause twice: first the condemned courtier says it, then the narrator — the charge confirmed by repeating it.') WHERE id = 'QR:PS:40:28-35:rel5a';
UPDATE qr_passage_section SET data_json = json_set(data_json, '$.relation.note', 'Pharaoh claims the phrase; the believer takes it back nine āyāt later.') WHERE id = 'QR:PS:40:28-35:rel8a';
UPDATE qr_passage_section SET data_json = json_set(data_json, '$.relation.note', '“Yours today” — spoken thirteen āyāt after the question.') WHERE id = 'QR:PS:40:28-35:rel9b';
UPDATE qr_passage_section SET data_json = json_set(data_json, '$.relation.note', 'The phrase taken back.') WHERE id = 'QR:PS:40:36-40:rel8b';
UPDATE qr_passage_section SET data_json = json_set(data_json, '$.relation.note', 'A tower to reach the heavens, against the heavens as the greater creation; 40:56 adds مَا هُمْ بِبَالِغِيهِ, “they will never reach it”.') WHERE id = 'QR:PS:40:36-40:rel10a';
UPDATE qr_passage_section SET data_json = json_set(data_json, '$.relation.note', 'One way only, never reversed: the charge, the witness, the verdict, the chains.') WHERE id = 'QR:PS:40:4-5:rel13a';
UPDATE qr_passage_section SET data_json = json_set(data_json, '$.relation.note', 'This passage depends on the one before: it starts a new sentence in its grammar (اسْتِئْنَاف بَيَانِيّ, an explanatory new start) but leans on it for its meaning.') WHERE id = 'QR:PS:40:4-5:rel15b';
UPDATE qr_passage_section SET data_json = json_set(data_json, '$.relation.note', 'Side by side: the invitation offered, then the invitation refused.') WHERE id = 'QR:PS:40:41-46:rel11a';
UPDATE qr_passage_section SET data_json = json_set(data_json, '$.relation.note', 'The believer’s warning at 40:43 becomes their own admission at 40:74.') WHERE id = 'QR:PS:40:47-50:rel11b';
UPDATE qr_passage_section SET data_json = json_set(data_json, '$.relation.note', 'Both put the question of proof to people already condemned.') WHERE id = 'QR:PS:40:47-50:rel12a';
UPDATE qr_passage_section SET data_json = json_set(data_json, '$.relation.note', 'The same clause, now in the narrator’s voice.') WHERE id = 'QR:PS:40:51-56:rel5b';
UPDATE qr_passage_section SET data_json = json_set(data_json, '$.relation.note', 'Word for word; the first adds asking forgiveness and glorifying, the second opens onto what is to come.') WHERE id = 'QR:PS:40:51-56:rel6a';
UPDATE qr_passage_section SET data_json = json_set(data_json, '$.relation.note', 'The same instruction, on the Prophet’s side.') WHERE id = 'QR:PS:40:51-56:rel7b';
UPDATE qr_passage_section SET data_json = json_set(data_json, '$.relation.note', 'Pride answered by a measurement: the heavens and the earth are a greater creation.') WHERE id = 'QR:PS:40:57-59:rel10b';
UPDATE qr_passage_section SET data_json = json_set(data_json, '$.relation.note', 'Two verdicts back to back, one on each side. Ibn ʿAṭiyya groups 40:6–9 for this reason; the pair is kept as a link, while the new start at 40:7 stays a boundary.') WHERE id = 'QR:PS:40:6-6:rel14a';
UPDATE qr_passage_section SET data_json = json_set(data_json, '$.relation.note', 'The hinge of the sūra.') WHERE id = 'QR:PS:40:60-68:rel2b';
UPDATE qr_passage_section SET data_json = json_set(data_json, '$.relation.note', 'Word for word, but for one pronoun.') WHERE id = 'QR:PS:40:60-68:rel3b';
UPDATE qr_passage_section SET data_json = json_set(data_json, '$.relation.note', 'The same verb, the opposite door.') WHERE id = 'QR:PS:40:69-76:rel1b';
UPDATE qr_passage_section SET data_json = json_set(data_json, '$.relation.note', 'The last stop of the one arc that never turns back.') WHERE id = 'QR:PS:40:69-76:rel13b';
UPDATE qr_passage_section SET data_json = json_set(data_json, '$.relation.note', 'The same verb, the opposite door; in both, someone else does the admitting.') WHERE id = 'QR:PS:40:7-9:rel1a';
UPDATE qr_passage_section SET data_json = json_set(data_json, '$.relation.note', 'The second of the two verdicts.') WHERE id = 'QR:PS:40:7-9:rel14b';
UPDATE qr_passage_section SET data_json = json_set(data_json, '$.relation.note', 'Word for word; here the outcome is left open.') WHERE id = 'QR:PS:40:77-78:rel6b';
UPDATE qr_passage_section SET data_json = json_set(data_json, '$.relation.note', 'The arcs of the ground and of the proof cross at both ends.') WHERE id = 'QR:PS:40:82-85:rel4b';
UPDATE qr_passage_section SET data_json = json_set(data_json, '$.relation.note', 'Outside the Fire, and inside it.') WHERE id = 'QR:PS:40:82-85:rel12b';
UPDATE qr_passage_section SET data_json = json_set(data_json, '$.relation.note', 'The far end of the root link: the attribute named in 40:3 is paid out at the sūra’s close.') WHERE id = 'QR:PS:40:82-85:rel16c';
